  Plaintext c0("c0");
  Plaintext c1("c1");
  Plaintext c3("c3");
  Plaintext c5("c5");
  Plaintext c7("c7");

  // Quotient Q = 2*c5*z + 2*c7*T3   (depth 4)
  Ciphertext c5z = z * c5;             // depth 2
